export const DHAKA_OUTER_AREAS = [
  "Ashulia",
  "Dhamrai",
  "Dohar",
  "Keraniganj",
  "Nawabganj",
  "Savar"
] as const;

export function getDeliveryChargeForDistrict(district: string, thana?: string) {
  const d = district.trim().toLowerCase();
  if (d === "dhaka") {
    if (!thana) return null;
    const t = thana.trim().toLowerCase();
    const isOuter = DHAKA_OUTER_AREAS.some(area => area.toLowerCase() === t);
    return isOuter ? 130 : 70;
  }
  return 130;
}
